        /** cost / sales over the trailing 30 days. Null when sales is zero. */
        acos: number | null;
        clicks: number;
        /** Spend over the trailing 30 days. Major units. */
        cost: number;
        impressions: number;
        /** sales / cost over the trailing 30 days. Null when cost is zero. */
