export type AutomationContext =
  | ListingContext
  | SellerContext
  | CampaignContext
  | PortfolioContext
  | MetricsContext
  | ChangeContext;

/** The context interface each stream type's handler receives. */
export interface StreamTypeContexts {
  ACCOUNT_STATUS_CHANGED: SellerContext;
  AD_CHANGE: ChangeContext;
  AD_GROUP_CHANGE: ChangeContext;
  ANY_OFFER_CHANGED: ListingContext;
  B2B_ANY_OFFER_CHANGED: ListingContext;
  BRANDED_ITEM_CONTENT_CHANGE: ListingContext;
  BUDGET_USAGE: CampaignContext | PortfolioContext;
  CAMPAIGN_CHANGE: ChangeContext;
  DATA_KIOSK_QUERY_PROCESSING_FINISHED: ListingContext;
  DETAIL_PAGE_TRAFFIC_EVENT: SellerContext;
  FBA_INVENTORY_AVAILABILITY_CHANGES: ListingContext;
  FBA_OUTBOUND_SHIPMENT_STATUS: SellerContext;
  FEED_PROCESSING_FINISHED: SellerContext;
  FULFILLMENT_ORDER_STATUS: SellerContext;
  ITEM_SALES_EVENT_CHANGE: SellerContext;
  LISTINGS_ITEM_ISSUES_CHANGE: ListingContext;
  LISTINGS_ITEM_MFN_QUANTITY_CHANGE: ListingContext;
  LISTINGS_ITEM_STATUS_CHANGE: ListingContext;
  ORDER_CHANGE: ListingContext;
  PRICING_HEALTH: ListingContext;
  REPORT_PROCESSING_FINISHED: ListingContext;
  SP_CONVERSION: MetricsContext;
  SP_TRAFFIC: MetricsContext;
  TARGET_CHANGE: ChangeContext;
}

export type AutomationHandler<C extends AutomationContext = AutomationContext> = (
  event: unknown,
  context: C,
) => C;
